const r = await tools.exec_command({
  cmd: "python3 - <<'PY'
from hashlib import sha256
from pathlib import Path
import re

snapshot = Path('kb/sources/.snapshots/same-model-different-harness-different-coding-agent-results.md')
report = Path('kb/sources/same-model-different-harness-different-coding-agent-results.ingest.md')
expected_sha = '029eaebf8b7342236b4b350e02a1bdb252ac8cd2e3027cbb9469b8799877bcb2'
expected_quotes = b'## Quotes\n\nNo source quotes have been retained yet.\n\n'

failures = []
if not report.is_file() or report.stat().st_size == 0:
    failures.append('output missing or empty')
    report_bytes = b''
else:
    report_bytes = report.read_bytes()

snapshot_bytes = snapshot.read_bytes()
actual_sha = sha256(snapshot_bytes).hexdigest()
if actual_sha != expected_sha:
    failures.append(f'snapshot checksum changed: {actual_sha}')

text = report_bytes.decode('utf-8') if report_bytes else ''
frontmatter = text.split('---', 2)[1] if text.startswith('---\n') and text.count('---') >= 2 else ''

def field(block, name):
    match = re.search(rf'(?m)^{re.escape(name)}:\s*(.*)$', block)
    if not match:
        return None
    value = match.group(1).strip()
    if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
        value = value[1:-1]
    return value

snapshot_text = snapshot_bytes.decode('utf-8')
snapshot_frontmatter = snapshot_text.split('---', 2)[1]
for name in ('source', 'captured', 'capture', 'capture_scope'):
    source_value = field(snapshot_frontmatter, name)
    report_value = field(frontmatter, name)
    if report_value != source_value:
        failures.append(f'capture metadata mismatch for {name}: snapshot={source_value!r}, report={report_value!r}')

if field(frontmatter, 'snapshot_sha256') != expected_sha:
    failures.append('ingest snapshot_sha256 missing or mismatched')
if field(frontmatter, 'occasion') is not None:
    failures.append('occasion field present despite occasion none')
for forbidden_field in ('source_snapshot', 'code_revisions', 'secondary_sources'):
    if field(frontmatter, forbidden_field) is not None:
        failures.append(f'forbidden field present: {forbidden_field}')

heading_starts = [m.start() for m in re.finditer(br'(?m)^## ', report_bytes)]
quote_starts = [m.start() for m in re.finditer(br'(?m)^## Quotes\n', report_bytes)]
if len(quote_starts) != 1:
    failures.append(f'expected exactly one Quotes block, found {len(quote_starts)}')
else:
    start = quote_starts[0]
    later = [pos for pos in heading_starts if pos > start]
    end = later[0] if later else len(report_bytes)
    actual_quotes = report_bytes[start:end]
    if actual_quotes != expected_quotes:
        failures.append(f'Quotes bytes differ: {actual_quotes!r}')
    if report_bytes[end:end + len(b'## Connections Found\n')] != b'## Connections Found\n':
        failures.append('Quotes block is not immediately before Connections Found')

for forbidden in (b'.snapshots/', b'related-systems/', b'.connect.md', b'## Code Grounding'):
    if forbidden in report_bytes:
        failures.append(f'forbidden report content present: {forbidden.decode()}')

if failures:
    print('HANDOFF_CHECK=FAIL')
    for failure in failures:
        print(f'- {failure}')
    raise SystemExit(1)
print('HANDOFF_CHECK=PASS')
print(f'output_bytes={len(report_bytes)}')
print(f'snapshot_sha256={actual_sha}')
print('capture_metadata=retained')
print('quotes=exact-and-positioned')
print('occasion=absent')
print('forbidden_fields_and_links=absent')
PY",
  workdir: "/home/zby/llm/commonplace",
  yield_time_ms: 10000,
  max_output_tokens: 20000
});
